import{_ as s,c as t,o as l,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"坎下坤上 師：","description":"京氏易傳 - 坎下坤上 師：","frontmatter":{"title":"坎下坤上 師：","description":"京氏易傳 - 坎下坤上 師："},"headers":[],"relativePath":"classics/jingshi/025.md","filePath":"classics/jingshi/025.md"}'),i={name:"classics/jingshi/025.md"};function r(c,a,o,p,d,u){return l(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"坎下坤上-師",tabindex:"-1"},[n("坎下坤上 師： "),e("a",{class:"header-anchor",href:"#坎下坤上-師","aria-label":"Permalink to “坎下坤上 師：”"},"​")],-1),e("p",null,"變離入陰，傷於正道；複本歸坎，陽在其中矣。【內卦坎為本宮。】處下卦之中，為陰之主，利於行師。《易》雲：“師者，眾也。”眾陰而宗於一陽，得其貞正也。與離為飛伏。【離入坎也。】陰陽相薄，剛柔遷位。【戊午火，己亥水。】世主三公，應為宗廟。",-1),e("p",null,"建始壬辰至丁酉，【清明至秋分。】積算起丁酉至丙申，週而復始。【金火入卦起算。】",-1),e("p",null,"五星從位起歲星，【歲星木入卦。】婁宿從位降戊午，【婁宿入坎卦歸魂六三爻。】分氣候二十八。【起算入卦吉凶。】",-1),e("p",null,"地下有水複本位，六五居陰處陽位；九二貞正，能為眾之主，不潰於眾。《易》雲：“師，貞丈人吉。”",-1),e("p",null,"入卦始於坎，陰陽相蕩；反至於極，則歸本，坎中男。【陽居九二，稱中男。】升降得失，吉凶悔吝，策於六爻；六爻之設，出於蓍；蓍之得象而卦生。積算起於五行，五行正則吉，極則兇。吉凶之象，顯於天地人事、日月歲時。",-1),e("p",null,"坎之變於艮，艮為少男。少男處卦之末，為極也。【震一陽居初爻，坎二陽處中，艮三陽處卦之末。故曰陽極為少男，又云止也。】次入艮卦。",-1)])])}const f=s(i,[["render",r]]);export{_ as __pageData,f as default};
